"use client"

import PhotoAlbumScrollTemplate from "@/components/ui/photo-album-scroll-template"

// Free Unsplash photos (unsplash.com/photos/<id>), cropped, graded to a soft
// film look and inlined as AVIF so the demo needs no network beyond the
// Google Fonts stylesheet:
// island 1717560620356-5b6603d13472, fruit in a net 1597244290595-161a0059ee6b,
// sailboat 1546214755-c5d22447b43b, beach umbrellas 1488462237308-ecaa28b729d7,
// rooftops 1782150626994-7ac41b3087e1, sky 1599768793949-2da217e9f093.
const ISLAND = "data:image/avif;base64,"
const FRUIT = "data:image/avif;base64,"
const SAIL = "data:image/avif;base64,"
const BEACH = "data:image/avif;base64,"
const ROOFS = "data:image/avif;base64,"
const SKY = "data:image/avif;base64,"

export default function Demo() {
  // w-full is load-bearing: 21st centres every demo in a flex wrapper.
  return (
    <div className="w-full">
      <PhotoAlbumScrollTemplate
        heroPhotos={[
          { src: ISLAND, alt: "A small palm island on a calm sea" },
          { src: FRUIT, alt: "Pineapples and bananas hanging in a net" },
        ]}
        cluster={[
          { src: SAIL, alt: "A sailboat on still water at dawn", label: "Your travels" },
          { src: BEACH, alt: "Orange beach umbrellas over deck chairs", label: "Your baby\ngrowing up" },
          { src: ROOFS, alt: "Rooftops above a blue bay", label: "Your wedding" },
        ]}
        sky={SKY}
      />
    </div>
  )
}
